const ensure=(ok,msg)=>{if(!ok)throw Error(msg);};
export const isoDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T12:00:00Z'))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
export const shiftDate=(value,days)=>{const d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);};
export const localToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export function deliveryRecord(s,p){
 const date=p.deliveredDate||localToday();ensure(isoDate(date)&&date<=localToday(),'Actual delivery date must be a valid date no later than today.');ensure(!s.actualDeparture||date>=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(s.actualDeparture)),'Delivery cannot precede actual departure.');
 const check=(a,ref)=>{ensure(['accurate','inaccurate','not_assessed'].includes(a),'Select an accuracy assessment.');ensure(a==='not_assessed'||ref?.trim(),'An accuracy assessment needs an evidence/reference explanation.');};
 let outcomes;
 if(p.lineOutcomes){ensure(Array.isArray(p.lineOutcomes)&&p.lineOutcomes.length===s.lines.length,'Provide one delivery outcome for each order line.');outcomes=s.lines.map(l=>{const matches=p.lineOutcomes.filter(o=>o.order===l.order&&o.sku===l.sku);ensure(matches.length===1,'Each order/SKU requires exactly one delivery outcome.');const o=matches[0],accuracy=o.accuracy||'not_assessed';ensure([o.accepted,o.returned].every(n=>Number.isInteger(n)&&n>=0)&&o.accepted+o.returned===l.packed,'Each line must reconcile accepted + returned to packed quantity.');check(accuracy,o.accuracyReference);return {order:l.order,sku:l.sku,accepted:o.accepted,returned:o.returned,accuracy,accuracyReference:o.accuracyReference?.trim()||''};});
 }else if(s.lines.length===1){const l=s.lines[0],accuracy=p.accuracy||'not_assessed';check(accuracy,p.accuracyReference);outcomes=[{order:l.order,sku:l.sku,accepted:p.accepted,returned:p.returned,accuracy,accuracyReference:p.accuracyReference?.trim()||''}];
 }else{ensure(p.returned===0,'Multi-order returns require order-line delivery quantities.');outcomes=s.lines.map(l=>({order:l.order,sku:l.sku,accepted:l.packed,returned:0,accuracy:'not_assessed',accuracyReference:''}));}
 ensure(outcomes.reduce((n,l)=>n+l.accepted,0)===p.accepted&&outcomes.reduce((n,l)=>n+l.returned,0)===p.returned,'Order-line outcomes must match the shipment totals.');
 return {accepted:p.accepted,returned:p.returned,deliveredDate:date,outcomes,time:new Date().toISOString()};
}
function outcomesFor(trip){if(!trip.delivery)return [];if(trip.delivery.outcomes)return trip.delivery.outcomes;if(trip.lines.length===1){const l=trip.lines[0];return [{order:l.order,sku:l.sku,accepted:trip.delivery.accepted,returned:trip.delivery.returned,accuracy:'not_assessed',accuracyReference:''}];}if(trip.delivery.returned===0&&trip.delivery.accepted===trip.lines.reduce((n,l)=>n+l.packed,0))return trip.lines.map(l=>({order:l.order,sku:l.sku,accepted:l.packed,returned:0,accuracy:'not_assessed',accuracyReference:''}));return [];}
export function logisticsSummary(state,{principal='',warehouse='',asOf=shiftDate(localToday(),-1)}={}){
 ensure(isoDate(asOf)&&asOf<=localToday(),'Choose a valid reporting date no later than today.');
 const scoped=state.orders.filter(o=>o.quantity>0&&(!principal||o.principal===principal)&&(!warehouse||o.warehouse===warehouse));
 const rows=scoped.map(o=>{const trips=state.shipments.filter(t=>t.dispatched&&t.lines.some(l=>l.order===o.id));let acceptedByDue=0,acceptedByReport=0,shipped=0,unknownAllocation=false,unknownDate=false,undelivered=false;const assessments=[];
 for(const t of trips){shipped+=t.lines.filter(l=>l.order===o.id).reduce((n,l)=>n+l.packed,0);if(!t.delivery){undelivered=true;continue;}const all=outcomesFor(t),lines=all.filter(l=>l.order===o.id);if(!lines.length){unknownAllocation=true;continue;}if(!isoDate(t.delivery.deliveredDate)){unknownDate=true;continue;}if(t.delivery.deliveredDate>asOf){undelivered=true;continue;}for(const l of lines){acceptedByReport+=l.accepted;if(isoDate(o.deliveryDueDate)&&t.delivery.deliveredDate<=o.deliveryDueDate)acceptedByDue+=l.accepted;assessments.push(l);}}
 const due=isoDate(o.deliveryDueDate)&&o.deliveryDueDate<=asOf;let otif='Not due';if(!isoDate(o.deliveryDueDate))otif='Commitment missing';else if(due){otif=acceptedByDue>=o.quantity?'Pass':unknownAllocation||unknownDate?'Evidence missing':'Miss';}
 const complete=shipped>=o.quantity&&!undelivered&&!unknownDate&&!unknownAllocation;let accuracy='Pending fulfillment';if(complete){if(acceptedByReport<o.quantity||assessments.some(l=>l.accuracy==='inaccurate'))accuracy='Error found';else if(assessments.length&&assessments.every(l=>l.accuracy==='accurate'&&l.accuracyReference))accuracy='Accurate';else accuracy='Not assessed';}else if(shipped>=o.quantity&&(unknownDate||unknownAllocation))accuracy='Evidence missing';
 return {order:o.id,principal:o.principal,warehouse:o.warehouse,quantity:o.quantity,promised:o.deliveryDueDate||null,acceptedByDue,acceptedByReport,otif,accuracy,due,complete};});
 const due=rows.filter(r=>r.due),evaluated=due.filter(r=>['Pass','Miss'].includes(r.otif)),passed=evaluated.filter(r=>r.otif==='Pass');const completed=rows.filter(r=>r.complete),candidates=rows.filter(r=>r.complete||r.accuracy==='Evidence missing'),assessed=completed.filter(r=>['Accurate','Error found'].includes(r.accuracy)),accurate=assessed.filter(r=>r.accuracy==='Accurate');
 return {asOf,orders:rows.length,due:due.length,otifEvaluated:evaluated.length,otifPass:passed.length,otifMiss:evaluated.length-passed.length,otifUnknown:due.length-evaluated.length,otifPct:evaluated.length?passed.length/evaluated.length*100:null,otifCoverage:due.length?evaluated.length/due.length*100:null,missingCommitment:rows.filter(r=>r.otif==='Commitment missing').length,completed:completed.length,accuracyAssessed:assessed.length,accurate:accurate.length,accuracyPct:assessed.length?accurate.length/assessed.length*100:null,accuracyCoverage:candidates.length?assessed.length/candidates.length*100:null,accuracyMissing:candidates.length-assessed.length,rows};
}
export const serviceTypes=['recordCommitment','serviceEvidence'];
export function serviceCommand(input,type,p,role){const allowed={recordCommitment:['planner','manager'],serviceEvidence:['checker','manager']};ensure(allowed[type]?.includes(role),'This action requires a different demonstration role.');const state=structuredClone(input),actor={planner:'OP-01',manager:'MGR-01',checker:'QC-02'}[role];let target;
 if(type==='recordCommitment'){const o=state.orders.find(o=>o.id===p.order);ensure(o,'Order not found.');ensure(isoDate(p.deliveryDueDate),'Enter a valid agreed delivery date.');ensure(p.reference?.trim(),'Record the source of the agreed customer commitment.');const departed=state.shipments.some(t=>t.dispatched&&t.lines.some(l=>l.order===o.id));ensure(!o.deliveryDueDate||!departed,'An existing commitment cannot be moved after dispatch.');o.deliveryDueDate=p.deliveryDueDate;o.commitmentReference=p.reference.trim();o.commitmentRecordedBy=actor;o.commitmentRecordedAt=new Date().toISOString();target=o.id;
 }else{const t=state.shipments.find(t=>t.id===p.shipment);ensure(t?.delivery,'Record a delivered shipment first.');ensure(p.reason?.trim(),'Record the evidence source/correction explanation.');ensure(!t.delivery.deliveredDate||p.deliveredDate===t.delivery.deliveredDate||role==='manager','Only a manager can correct a recorded actual delivery date.');const previous=structuredClone(t.delivery);const d=deliveryRecord(t,{...p,accepted:t.delivery.accepted,returned:t.delivery.returned});t.serviceEvidenceHistory??=[];t.serviceEvidenceHistory.push({previous,actor,reason:p.reason,time:new Date().toISOString()});t.delivery=d;target=t.id;}
 state.events.unshift({id:`EV-${Date.now()}-${state.events.length}`,time:new Date().toISOString(),actor,role,shipment:p.shipment||'',action:type,detail:p.reference||p.reason});return {state,result:target};
}
